import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2022-11-17","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-11-17","date":"2022-11-17T00:00:00.000Z","updated":"2022-11-18T00:00:00.000Z","tags":["Ceph","BlueStore","删除范围","RGW","性能优化","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-11-17.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-11-17.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-11-17.md"};function o(n,e,s,d,h,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="与会人员" tabindex="-1">与会人员 <a class="header-anchor" href="#与会人员" aria-label="Permalink to &quot;与会人员&quot;">​</a></h4><ul><li>主持人：Mark</li><li>其他参与者：Casey</li></ul><h4 id="会议主要议题" tabindex="-1">会议主要议题 <a class="header-anchor" href="#会议主要议题" aria-label="Permalink to &quot;会议主要议题&quot;">​</a></h4><ol><li><p><strong>Adam的工作进展</strong></p><ul><li>Adam致力于改进BlueStore中共享blob的处理方式，特别是在快照处理方面。</li><li>初始测试显示了性能提升，但CPU使用率增加，性能提升不显著。</li><li>考虑将新extent添加到现有共享blob中，而不是创建新的共享blob，可能无需改变磁盘格式。</li></ul></li><li><p><strong>性能问题讨论</strong></p><ul><li>讨论了删除范围在RGW日志修剪中的使用问题。</li><li>发现处理删除范围时，下游和上游的行为不一致。</li><li>探讨了调整RocksDB配置以优化删除范围处理的解决方案。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>Mark将跟进Adam的工作进展，并深入理解删除范围问题时的情况。</li><li>Casey将跟进邮件讨论，确保上下游行为一致，寻找解决方案。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续监控和评估Adam的新方法，以解决快照处理中的性能问题。</li><li>确保上下游在处理删除范围时的一致性，并寻找优化方案。</li></ul><h4 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h4><ul><li>Mark将更新拉取请求并跟进Adam的工作。</li><li>Casey将通过邮件继续讨论删除范围问题，并寻找解决方案。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>Mark因健康问题未能审查拉取请求，将在下周进行更新。</li><li>会议结束时，Mark提醒大家注意健康，并祝愿大家下周顺利。</li></ul><h4 id="会议结束时间" tabindex="-1">会议结束时间 <a class="header-anchor" href="#会议结束时间" aria-label="Permalink to &quot;会议结束时间&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，无其他紧急事项。</li></ul><p>在本次会议中，与会人员讨论了BlueStore中共享blob的改进、删除范围在RGW日志修剪中的使用问题以及相应的性能优化措施。会议决定了后续行动计划，包括跟进Adam的工作以及解决删除范围问题。</p>',14)])])}const p=a(r,[["render",o]]);export{_ as __pageData,p as default};
